    nrows, ncols = len(grid), len(grid[0])
    n = round(((4 * nrows + 5) ** 0.5 - 1) / 2)
    if n * n + n - 1 != nrows or nrows != ncols:
        raise ValueError("unexpected grid dimensions")

    pitch = n + 1
    motif = None
    for i in range(n):
        for j in range(n):
            r0, c0 = i * pitch, j * pitch
            block = [grid[r0 + r][c0:c0 + n] for r in range(n)]
            if any(v == 2 for row in block for v in row):
                motif = [[2 if v == 2 else 0 for v in row] for row in block]
                break
        if motif is not None:
            break
    if motif is None:
        raise ValueError("no motif found")

    out = [[0] * ncols for _ in range(nrows)]
    for i in range(n):
        for j in range(n):
            if motif[i][j] != 2:
                continue
            r0, c0 = i * pitch, j * pitch
            for r in range(n):
                for c in range(n):
                    if motif[r][c] == 2:
                        out[r0 + r][c0 + c] = 2
            out[r0 + i][c0 + j] = 8
    return out
'''
